     7→ */
     8→import React, { createContext, useState, useEffect, useCallback } from 'react';
     9→import type { ReactNode } from 'react';
    10→import type { User, Session } from '@supabase/supabase-js';
    11→import { supabase, signIn as supabaseSignIn, signUp as supabaseSignUp, signOut as supabaseSignOut } from '../services/supabase';
    12→import type { AuthContextType, UserProfile, UserRole } from '../types';
    13→
    14→// Create context with default values
    15→// eslint-disable-next-line react-refresh/only-export-components
    16→export const AuthContext = createContext<AuthContextType>({
    17→  user: null,
    18→  session: null,
    19→  userProfile: null,
    20→  loading: true,
    21→  signIn: async () => {},
    22→  signUp: async () => {},
    23→  signOut: async () => {},
    24→  isAuthenticated: false,
    25→  revalidateSession: async () => false,
    26→});
    27→
    28→interface AuthProviderProps {
    29→  children: ReactNode;
    30→}
    31→
    32→/**
    33→ * AuthProvider component - Wrap app with this to provide auth state
    34→ */
    35→export const AuthProvider: React.FC<AuthProviderProps> = ({ children }) => {
    36→  const [user, setUser] = useState<User | null>(null);
    37→  const [session, setSession] = useState<Session | null>(null);
    38→  const [userProfile, setUserProfile] = useState<UserProfile | null>(null);
    39→  const [loading, setLoading] = useState(true);
    40→
    41→  // Track if we're currently fetching a profile to prevent concurrent fetches
    42→  const fetchingProfileRef = React.useRef(false);
    43→  // Track initialization to prevent duplicate fetches
    44→  const initializedRef = React.useRef(false);
    45→
    46→  /**
    47→   * Fetch user profile from database with timeout, retry logic, and improved error handling
    48→   * Bug fix: Don't clear userProfile on transient errors (network/timeout), only on permanent errors
    49→   */
    50→  const fetchUserProfile = useCallback(async (userId: string, retryCount = 0): Promise<void> => {
    51→    const MAX_RETRIES = 1;
    52→    const RETRY_DELAY = 1000; // 1 second
    53→
    54→    // Prevent concurrent fetches
    55→    if (fetchingProfileRef.current) {
    56→      console.log('[AuthContext] Profile fetch already in progress, skipping...');
    57→      return;
    58→    }
    59→
    60→    fetchingProfileRef.current = true;
    61→    console.log('[AuthContext] Starting profile fetch for user:', userId, retryCount > 0 ? `(retry ${retryCount})` : '');
    62→
    63→    try {
    64→      // Create a timeout promise (10 seconds)
    65→      const timeoutPromise = new Promise<never>((_, reject) => {
    66→        setTimeout(() => reject(new Error('Profile fetch timeout')), 10000);
    67→      });
    68→
    69→      // Race between fetch and timeout
    70→      const fetchPromise = supabase
    71→        .from('user_profiles')
    72→        .select('*')
    73→        .eq('id', userId)
    74→        .single();
    75→
    76→      const result = await Promise.race([fetchPromise, timeoutPromise]);
    77→      const { data, error } = result as Awaited<typeof fetchPromise>;
    78→
    79→      if (error) {
    80→        console.error('[AuthContext] Error fetching user profile:', error);
    81→
    82→        // Permanent error: profile doesn't exist
    83→        if ('code' in error && error.code === 'PGRST116') {
    84→          console.error('[AuthContext] User profile not found in database (PGRST116). User may need to complete registration.');
    85→          setUserProfile(null);
    86→          return;
    87→        }
    88→
    89→        // Transient error: network/timeout - retry once, but don't clear existing profile
    90→        if (retryCount < MAX_RETRIES) {
    91→          console.warn('[AuthContext] Transient error fetching profile, will retry in', RETRY_DELAY, 'ms');
    92→          fetchingProfileRef.current = false;
    93→          await new Promise(resolve => setTimeout(resolve, RETRY_DELAY));
    94→          return fetchUserProfile(userId, retryCount + 1);
    95→        }
    96→
    97→        // Max retries reached - log warning but keep existing userProfile
    98→        console.warn('[AuthContext] Max retries reached for profile fetch. Keeping existing profile to prevent auth loss.');
    99→        return;
   100→      }
   101→
   102→      console.log('[AuthContext] Profile fetched successfully:', data);
   103→      setUserProfile(data as UserProfile);
   104→    } catch (error) {
   105→      console.error('[AuthContext] Error fetching user profile:', error);
   106→
   107→      // On timeout or network error, try to retry
   108→      if (retryCount < MAX_RETRIES) {
   109→        console.warn('[AuthContext] Network/timeout error, will retry in', RETRY_DELAY, 'ms');
   110→        fetchingProfileRef.current = false;
   111→        await new Promise(resolve => setTimeout(resolve, RETRY_DELAY));
   112→        return fetchUserProfile(userId, retryCount + 1);
   113→      }
   114→
   115→      // Max retries reached - log warning but don't clear existing profile
   116→      console.warn('[AuthContext] Max retries reached after exception. Keeping existing profile to prevent auth loss.');
   117→    } finally {
   118→      fetchingProfileRef.current = false;
   119→      console.log('[AuthContext] Profile fetch completed');
   120→    }
   121→  }, []); // Empty deps - function doesn't depend on any state
   122→
   123→  /**
   124→   * Revalidate session by fetching current session from Supabase
   125→   * This method allows components to manually trigger session resync
   126→   * Returns true if a valid session was found and state updated
   127→   */
   128→  const revalidateSession = useCallback(async (): Promise<boolean> => {
   129→    console.log('[AuthContext] Manual session revalidation triggered');
   130→
   131→    try {
   132→      const { data: { session: currentSession }, error } = await supabase.auth.getSession();
   133→
   134→      if (error) {
   135→        console.error('[AuthContext] Error during revalidation:', error);
   136→        return false;
   137→      }
   138→
   139→      if (currentSession) {
   140→        console.log('[AuthContext] Revalidation found valid session, updating state');
   141→        setSession(currentSession);
   142→        setUser(currentSession.user);
   143→
   144→        // Fetch profile if we don't have it or user ID changed
   145→        if (!userProfile || userProfile.id !== currentSession.user.id) {
   146→          await fetchUserProfile(currentSession.user.id);
   147→        }
   148→
   149→        return true;
   150→      } else {
   151→        console.log('[AuthContext] Revalidation found no session');
   152→        setSession(null);
   153→        setUser(null);
   154→        setUserProfile(null);
   155→        return false;
   156→      }
   157→    } catch (error) {
   158→      console.error('[AuthContext] Exception during revalidation:', error);
   159→      return false;
   160→    }
   161→  }, [userProfile, fetchUserProfile]);
   162→
   163→  /**
   164→   * Validate session matches current Supabase session
   165→   * Used by periodic validation and window focus handlers
   166→   */
   167→  const validateSession = useCallback(async (): Promise<void> => {
   168→    try {
   169→      const { data: { session: currentSession }, error } = await supabase.auth.getSession();
   170→
   171→      if (error) {
   172→        console.error('[SessionValidation] Error fetching session:', error);
   173→        return;
   174→      }
   175→
   176→      // Compare current session with React state
   177→      const hasSessionMismatch =
   178→        (!!currentSession !== !!session) ||
   179→        (currentSession?.access_token !== session?.access_token);
   180→
   181→      if (hasSessionMismatch) {
   182→        console.warn('[SessionValidation] Session mismatch detected! Updating React state...');
   183→        console.log('[SessionValidation] Current session:', currentSession ? 'Has token' : 'No session');
   184→        console.log('[SessionValidation] React state session:', session ? 'Has token' : 'No session');
   185→
   186→        // Update state to match Supabase
   187→        setSession(currentSession);
   188→        setUser(currentSession?.user ?? null);
   189→
   190→        if (currentSession?.user) {
   191→          await fetchUserProfile(currentSession.user.id);
   192→        } else {
   193→          setUserProfile(null);
   194→        }
   195→      } else {
   196→        console.log('[SessionValidation] Session validation passed - state is synchronized');
   197→      }
   198→    } catch (error) {
   199→      console.error('[SessionValidation] Exception during validation:', error);
   200→    }
   201→  }, [session, fetchUserProfile]);
   202→
   203→  /**
   204→   * Initialize auth state and set up listener
   205→   */
   206→  useEffect(() => {
   207→    // Prevent double initialization in development mode (React strict mode)
   208→    if (initializedRef.current) {
   209→      console.log('[AuthContext] Already initialized, skipping...');
   210→      return;
   211→    }
   212→
   213→    initializedRef.current = true;
   214→    console.log('[AuthContext] Initializing authentication...');
   215→
   216→    // Get initial session
   217→    const initializeAuth = async () => {
   218→      try {
   219→        const { data: { session: initialSession }, error } = await supabase.auth.getSession();
   220→
   221→        if (error) {
   222→          console.error('[AuthContext] Error getting initial session:', error);
   223→        }
   224→
   225→        console.log('[AuthContext] Initial session:', initialSession ? 'Has session' : 'No session');
   226→        setSession(initialSession);
   227→        setUser(initialSession?.user ?? null);
   228→
   229→        if (initialSession?.user) {
   230→          console.log('[AuthContext] Fetching profile for user:', initialSession.user.id);
   231→          await fetchUserProfile(initialSession.user.id);
   232→        }
   233→      } catch (error) {
   234→        console.error('[AuthContext] Error initializing auth:', error);
   235→      } finally {
   236→        console.log('[AuthContext] Initialization complete, setting loading to false');
   237→        setLoading(false);
   238→      }
   239→    };
   240→
   241→    initializeAuth();
   242→
   243→    // Listen for auth state changes
   244→    const { data: { subscription } } = supabase.auth.onAuthStateChange(
   245→      async (event, newSession) => {
   246→        const timestamp = new Date().toISOString();
   247→        console.log(`[AuthContext] ${timestamp} - Auth state changed:`, event);
   248→        console.log('[AuthContext] New session:', newSession ? 'Has session' : 'No session');
   249→
   250→        if (newSession) {
   251→          const expiresAt = newSession.expires_at ? new Date(newSession.expires_at * 1000).toISOString() : 'Unknown';
   252→          console.log('[AuthContext] Token expires at:', expiresAt);
   253→        }
   254→
   255→        // Ignore INITIAL_SESSION event to prevent duplicate fetches
   256→        if (event === 'INITIAL_SESSION') {
   257→          console.log('[AuthContext] Ignoring INITIAL_SESSION event');
   258→          return;
   259→        }
   260→
   261→        // Handle TOKEN_REFRESHED event explicitly
   262→        if (event === 'TOKEN_REFRESHED') {
   263→          console.log('[AuthContext] TOKEN_REFRESHED event - updating session in React state');
   264→          setSession(newSession);
   265→          setUser(newSession?.user ?? null);
   266→
   267→          // Profile should still be valid, but refresh if user changed
   268→          if (newSession?.user && (!userProfile || userProfile.id !== newSession.user.id)) {
   269→            console.log('[AuthContext] User changed during refresh, fetching new profile');
   270→            await fetchUserProfile(newSession.user.id);
   271→          } else {
   272→            console.log('[AuthContext] Token refreshed, keeping existing profile');
   273→          }
   274→
   275→          setLoading(false);
   276→          return;
   277→        }
   278→
   279→        // Handle other events (SIGNED_IN, SIGNED_OUT, USER_UPDATED)
   280→        console.log('[AuthContext] Handling event:', event);
   281→        console.log('[AuthContext] Before state update - user:', user ? user.id : 'null', ', profile:', userProfile ? userProfile.id : 'null');
   282→
   283→        setSession(newSession);
   284→        setUser(newSession?.user ?? null);
   285→
   286→        if (newSession?.user) {
   287→          console.log('[AuthContext] Fetching profile for user:', newSession.user.id);
   288→          await fetchUserProfile(newSession.user.id);
   289→        } else {
   290→          console.log('[AuthContext] No user in session, clearing profile');
   291→          setUserProfile(null);
   292→        }
   293→
   294→        console.log('[AuthContext] After state update - user:', newSession?.user ? newSession.user.id : 'null');
   295→
   296→        // Ensure loading is false after auth state change
   297→        setLoading(false);
   298→      }
   299→    );
   300→
   301→    // Cleanup subscription on unmount
   302→    return () => {
   303→      console.log('[AuthContext] Cleaning up subscription');
   304→      subscription.unsubscribe();
   305→      initializedRef.current = false;
   306→    };
   307→    // eslint-disable-next-line react-hooks/exhaustive-deps
   308→  }, []); // Empty deps array intentional - initialize once on mount
   309→
   310→  /**
   311→   * Periodic session validation (every 5 minutes)
   312→   * Catches cases where onAuthStateChange missed an event
   313→   */
   314→  useEffect(() => {
   315→    console.log('[SessionValidation] Setting up periodic validation (every 5 minutes)');
   316→
   317→    const VALIDATION_INTERVAL = 5 * 60 * 1000; // 5 minutes
   318→
   319→    const intervalId = setInterval(() => {
   320→      console.log('[SessionValidation] Running periodic validation check...');
   321→      validateSession();
   322→    }, VALIDATION_INTERVAL);
   323→
   324→    // Cleanup interval on unmount
   325→    return () => {
   326→      console.log('[SessionValidation] Cleaning up periodic validation');
   327→      clearInterval(intervalId);
   328→    };
   329→  }, [validateSession]);
   330→
   331→  /**
   332→   * Window focus session validation
   333→   * Re-validates session when user returns to the tab
   334→   */
   335→  useEffect(() => {
   336→    console.log('[SessionValidation] Setting up window focus listener');
   337→
   338→    const handleWindowFocus = async () => {
   339→      console.log('[SessionValidation] Window gained focus, validating session...');
   340→
   341→      // Check if session is close to expiry (within 5 minutes)
   342→      if (session?.expires_at) {
   343→        const expiresAt = session.expires_at * 1000; // Convert to milliseconds
   344→        const now = Date.now();
   345→        const timeUntilExpiry = expiresAt - now;
   346→        const REFRESH_THRESHOLD = 5 * 60 * 1000; // 5 minutes
   347→
   348→        if (timeUntilExpiry < REFRESH_THRESHOLD && timeUntilExpiry > 0) {
   349→          console.log('[SessionValidation] Token close to expiry, refreshing...');
   350→          try {
   351→            const { error } = await supabase.auth.refreshSession();
   352→            if (error) {
   353→              console.error('[SessionValidation] Error refreshing session:', error);
   354→            } else {
   355→              console.log('[SessionValidation] Session refreshed successfully');
   356→            }
   357→          } catch (error) {
   358→            console.error('[SessionValidation] Exception refreshing session:', error);
   359→          }
   360→        }
   361→      }
   362→
   363→      // Always validate to catch desynchronization
   364→      await validateSession();
   365→    };
   366→
   367→    window.addEventListener('focus', handleWindowFocus);
   368→
   369→    // Cleanup listener on unmount
   370→    return () => {
   371→      console.log('[SessionValidation] Cleaning up window focus listener');
   372→      window.removeEventListener('focus', handleWindowFocus);
   373→    };
   374→  }, [session, validateSession]);
   375→
   376→  /**
   377→   * Sign in handler
   378→   */
   379→  const handleSignIn = async (email: string, password: string): Promise<void> => {
   380→    console.log('[AuthContext] handleSignIn called for:', email);
   381→    try {
   382→      const { user: signedInUser, session: signedInSession, error } = await supabaseSignIn(email, password);
   383→
   384→      console.log('[AuthContext] Sign in result:', {
   385→        user: signedInUser ? 'User returned' : 'No user',
   386→        session: signedInSession ? 'Session returned' : 'No session',
   387→        error: error ? error.message : 'No error'
   388→      });
   389→
   390→      if (error) {
   391→        throw new Error(error.message);
   392→      }
   393→
   394→      // Don't set state here - let onAuthStateChange handle it
   395→      // This prevents race conditions
   396→
   397→      // Update last login timestamp
   398→      if (signedInUser) {
   399→        await supabase
   400→          .from('user_profiles')
   401→          .update({ last_login: new Date().toISOString() })
   402→          .eq('id', signedInUser.id);
   403→      }
   404→
   405→      // onAuthStateChange will fire and update the state
   406→      // Wait a bit for it to process
   407→      await new Promise(resolve => setTimeout(resolve, 100));
   408→    } catch (error) {
   409→      console.error('[AuthContext] Sign in error:', error);
   410→      throw error;
   411→    }
   412→  };
   413→
   414→  /**
   415→   * Sign up handler
   416→   */
   417→  const handleSignUp = async (
   418→    email: string,
   419→    password: string,
   420→    fullName: string,
   421→    userType: 'funcionario' | 'cliente',
   422→    role: UserRole = 'user' as UserRole,
   423→    companyName?: string,
   424→    clientId?: string
   425→  ): Promise<void> => {
   426→    setLoading(true);
   427→    try {
   428→      const { user: newUser, error } = await supabaseSignUp(email, password, {
   429→        full_name: fullName,
   430→      });
   431→
   432→      if (error) {
   433→        throw new Error(error.message);
   434→      }
   435→
   436→      // Create user profile record
   437→      if (newUser) {
   438→        // For clients, automatically set role to 'cliente'
   439→        const finalRole = userType === 'cliente' ? ('cliente' as UserRole) : role;
   440→
   441→        const { error: profileError } = await supabase
   442→          .from('user_profiles')
   443→          .insert({
   444→            id: newUser.id,
   445→            full_name: fullName,
   446→            role: finalRole,
   447→            user_type: userType,
   448→            is_active: true,
   449→            company_name: companyName || null,
   450→            client_id: clientId || null,
   451→          });
   452→
   453→        if (profileError) {
   454→          console.error('Error creating user profile:', profileError);
   455→          throw new Error('Failed to create user profile');
   456→        }
   457→
   458→        await fetchUserProfile(newUser.id);
   459→      }
   460→    } catch (error) {
   461→      console.error('Sign up error:', error);
   462→      throw error;
   463→    } finally {
   464→      setLoading(false);
   465→    }
   466→  };
   467→
   468→  /**
   469→   * Sign out handler
   470→   */
   471→  const handleSignOut = async (): Promise<void> => {
   472→    setLoading(true);
   473→    try {
   474→      const { error } = await supabaseSignOut();
   475→
   476→      if (error) {
   477→        throw new Error(error.message);
   478→      }
   479→
   480→      setUser(null);
   481→      setSession(null);
   482→      setUserProfile(null);
   483→    } catch (error) {
   484→      console.error('Sign out error:', error);
   485→      throw error;
   486→    } finally {
   487→      setLoading(false);
   488→    }
   489→  };
   490→
   491→  // Computed value for authentication status
   492→  const isAuthenticated = !!user && !!session;
   493→
   494→  const value: AuthContextType = {
   495→    user,
   496→    session,
   497→    userProfile,
   498→    loading,
   499→    signIn: handleSignIn,
   500→    signUp: handleSignUp,
   501→    signOut: handleSignOut,
   502→    isAuthenticated,
   503→    revalidateSession,
   504→  };
   505→
   506→  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
   507→};
